SYNONYMS = {
    'bills': 'invoices', 'unpaid': 'awaiting payment', 'purchases': 'expenses',
    'lodging': 'hotels', 'holiday': 'vacation', 'papers': 'documents',
    'novices': 'beginners', 'pictures': 'photographs', 'clips': 'footage',
    'songs': 'tracks', 'faulty': 'defective', 'patches': 'changes',
    'buyers': 'customers', 'clients': 'customers', 'drafts': 'manuscripts',
    'cargo': 'freight', 'authorization': 'permits', 'rusted': 'corroded',
    'outfits': 'costumes', 'phone': 'mobile', 'machines': 'instances',
    'misannotated': 'incorrectly assigned', 'newborns': 'birth',
}

def corpus() -> dict:
    namespace=uuid.UUID('B0800000-0000-4000-8000-000000000001')
    records=[]; queries=[]
    for family_index,line in enumerate(FAMILIES.splitlines()):
        parts=line.split('|')
        if len(parts)!=12: raise ValueError((family_index, len(parts)))
        family,*values=parts; labels=values[:8]; semantic=values[8:10]; absent=values[10]
        partition='tuning' if family_index<16 else 'heldout'
        ids=[]
        for index,label in enumerate(labels):
            item=str(uuid.uuid5(namespace,f'{family}:{index}')).upper(); ids.append(item)
            records.append(dict(id=item,family=family,partition=partition,text=label))
        for index,(kind,text,relevant) in enumerate([('direct',labels[0],[ids[0]]),
            ('semantic',semantic[0],[ids[1]]),('semantic',semantic[1],[ids[2]]),('none',absent,[])]):
            queries.append(dict(id=f'{partition}-{family_index:02}-{index}',family=family,partition=partition,kind=kind,text=text,relevant=relevant))
    assert len(records)==512 and len(queries)==256
    assert max(len(row['text'].encode()) for row in records+queries)<=128
    assert sum(len(row['text'].encode()) for row in records)<=65536
    return dict(format='MacExplorer.RelatedNames.Generated',version=1,records=records,queries=queries,
        synonyms=SYNONYMS, pooling='equal-subword-mean-l2-v1',
        tuningRule='highest positive MRR among thresholds with zero tuning no-match hits; tie: recall, precision, higher threshold',
        thresholds=[i/100 for i in range(101)], displayLimit=5)

if __name__ == '__main__': print(json.dumps(corpus(),ensure_ascii=False,sort_keys=True,indent=2))
